package io.github.rivomesh.acceptance;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import io.github.rivomesh.*;
import io.github.rivomesh.cdc.*;
import io.github.rivomesh.platform.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.TimeUnit;

/** Real HTTP controller, immutable config worker files and database checkpoints across password rotation/restore. */
public final class ConfigurationAcceptance {
    static final String TOKEN="configuration-acceptance-private-token-at-least-24";
    static final String OPERATOR="configuration-managed-operator-token-at-least32",ROTATED_OPERATOR="configuration-rotated-operator-token-at-least32";
    static final class Response {final int status;final JsonNode body;Response(int status,JsonNode body){this.status=status;this.body=body;}}
    final String id="config_"+UUID.randomUUID().toString().replace("-","").substring(0,20);
    final Path directory=Paths.get(System.getenv("RIVOMESH_CONFIGURATION_DIR"));
    final PipelineConfig pipeline=new PipelineConfig();final PlatformConfig platform=new PlatformConfig();
    String endpoint,targetPassword="Sync@Test123";TaskService service;ConsoleServer server;
    static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
    interface Condition{boolean ready()throws Exception;}
    void await(Condition condition)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(90);Exception last=null;while(System.nanoTime()<end){try{if(condition.ready())return;}catch(Exception retry){last=retry;}Thread.sleep(100);}throw new AssertionError("Timed out: "+(last==null?"":last.getClass().getName()));}
    Response request(String path,String method,JsonNode body,String request)throws Exception{return requestAs(TOKEN,path,method,body,request);}
    Response requestAs(String token,String path,String method,JsonNode body,String request)throws Exception{
        HttpURLConnection connection=(HttpURLConnection)new URL(endpoint+path).openConnection();connection.setConnectTimeout(3000);connection.setReadTimeout(10000);connection.setRequestMethod(method);connection.setRequestProperty("Authorization","Bearer "+token);if(request!=null)connection.setRequestProperty("X-Request-ID",request);if(body!=null){connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");byte[] bytes=Model.JSON.writeValueAsBytes(body);connection.setFixedLengthStreamingMode(bytes.length);try(OutputStream output=connection.getOutputStream()){output.write(bytes);}}
        try{int status=connection.getResponseCode();try(InputStream input=status>=400?connection.getErrorStream():connection.getInputStream()){return new Response(status,Model.JSON.readTree(input));}}finally{connection.disconnect();}
    }
    String path(){return "/api/tasks/"+id;}
    JsonNode task()throws Exception{Response response=request(path(),"GET",null,null);require(response.status==200,"Task view unavailable");return response.body;}
    void action(String action)throws Exception{ObjectNode body=Model.JSON.createObjectNode();body.put("action",action);body.put("expectedRevision",task().path("revision").asText());require(request(path()+"/actions","POST",body,"action_"+UUID.randomUUID().toString().replace("-","")).status==202,"Control action rejected");await(()->{JsonNode operations=task().path("operations");return operations.size()>0&&!"PENDING".equals(operations.get(operations.size()-1).path("status").asText());});if(!"CHECK".equals(action)){JsonNode operations=task().path("operations"),operation=operations.get(operations.size()-1);require("SUCCEEDED".equals(operation.path("status").asText()),"Action failed: "+operation.path("code").asText());}}
    void stop()throws Exception{action("STOP");await(()->task().path("workerState").asText().equals("STOPPED"));}
    void source(String statement)throws Exception{try(Connection connection=JdbcConnections.open("com.mysql.cj.jdbc.Driver","jdbc:mysql://mysql:3306/?useSSL=false&allowPublicKeyRetrieval=true&connectTimeout=3000&socketTimeout=10000","root","Sync@Test123");Statement sql=connection.createStatement()){sql.execute(statement);}}
    void target(String statement)throws Exception{try(Connection connection=JdbcConnections.open("org.postgresql.Driver",pipeline.targets.get(0).url,"sync_test",targetPassword);Statement sql=connection.createStatement()){sql.execute(statement);}}
    long rows()throws Exception{try(Connection connection=JdbcConnections.open("org.postgresql.Driver",pipeline.targets.get(0).url,"sync_test",targetPassword);Statement sql=connection.createStatement();ResultSet result=sql.executeQuery("SELECT count(*) FROM "+Sql.pg(id+"_copy")+".items")){result.next();return result.getLong(1);}}
    void startController()throws Exception{service=new TaskService(platform);server=new ConsoleServer(platform,service);server.start();endpoint="http://127.0.0.1:"+server.port();}
    void closeController()throws Exception{if(server!=null){server.close();server=null;}if(service!=null){service.close();service=null;}}
    ObjectNode edited(String password)throws Exception{Response response=request(path()+"/configuration","GET",null,null);require(response.status==200,"Configuration read failed");String text=response.body.toString();require(!text.contains("Sync@Test123")&&!text.contains("Rotated@Test123"),"Configuration leaked a saved credential");ObjectNode body=Model.JSON.createObjectNode();body.put("expectedRevision",response.body.path("revision").asText());body.set("config",response.body.path("config").deepCopy());((ObjectNode)body.path("config").path("targets").get(0)).put("password",password);return body;}
    Response commit(ObjectNode body,String request)throws Exception{Response[] committed={null};await(()->{Response result=request(path()+"/configuration","PUT",body,request);if(result.status==409&&result.body.path("code").asText().equals("TASK_BUSY"))return false;require(result.status==200,"Config commit rejected: "+result.body.path("code").asText());committed[0]=result;return true;});return committed[0];}
    void exerciseAccounts(JdbcJournal journal,String generation,String snapshot)throws Exception{
        Response directory=request("/api/accounts","GET",null,null);require(directory.status==200&&directory.body.path("mode").asText().equals("CONFIG"),"Bootstrap directory not available");
        ObjectNode activate=Model.JSON.createObjectNode().put("expectedRevision",directory.body.path("revision").asText());Response managed=request("/api/accounts/activate","POST",activate,"activate_pipeline_accounts");require(managed.status==200,"Managed activation failed");
        ObjectNode create=Model.JSON.createObjectNode().put("expectedRevision",managed.body.path("revision").asText()).put("id","pipeline-operator").put("role","OPERATOR").put("enabled",true).put("token",OPERATOR);create.putArray("taskIds").add(id);Response created=request("/api/accounts","POST",create,"create_pipeline_operator");require(created.status==201,"Operator creation failed");require(requestAs(OPERATOR,path(),"GET",null,null).status==200,"Assigned task inaccessible");require(requestAs(OPERATOR,"/api/accounts","GET",null,null).status==403,"Operator accessed account administration");
        ObjectNode empty=Model.JSON.createObjectNode().put("expectedRevision",created.body.path("revision").asText()).put("role","VIEWER").put("enabled",true);empty.putArray("taskIds");Response changed=request("/api/accounts/pipeline-operator","PUT",empty,"revoke_pipeline_operator");require(changed.status==200,"Grant revocation failed");require(requestAs(OPERATOR,path(),"GET",null,null).status==404,"Revoked task remained visible");
        Response rotated=request("/api/accounts/pipeline-operator/token","POST",Model.JSON.createObjectNode().put("expectedRevision",changed.body.path("revision").asText()).put("token",ROTATED_OPERATOR),"rotate_pipeline_operator");require(rotated.status==200,"Operator rotation failed");require(requestAs(OPERATOR,"/api/session","GET",null,null).status==401&&requestAs(ROTATED_OPERATOR,"/api/session","GET",null,null).status==200,"Credential revocation was not immediate");
        Response last=request("/api/accounts/legacy-admin","DELETE",Model.JSON.createObjectNode().put("expectedRevision",rotated.body.path("revision").asText()),"deny_pipeline_last_admin");require(last.status==409&&last.body.path("code").asText().equals("ACCOUNT_LAST_ADMIN"),"Last administrator guard failed");
        source("UPDATE "+Sql.mysql(id)+".items SET value='after access change' WHERE id=1");await(()->{try(Connection c=JdbcConnections.open("org.postgresql.Driver",pipeline.targets.get(0).url,"sync_test",targetPassword);Statement query=c.createStatement();ResultSet row=query.executeQuery("SELECT value FROM "+Sql.pg(id+"_copy")+".items WHERE id=1")){return row.next()&&row.getString(1).equals("after access change");}});
        require(generation.equals(journal.status().get("generation"))&&snapshot.equals(journal.snapshot("source",TableSchema.identity(id,"","items")).snapshotId),"Account changes reset dataflow identity");System.out.println("ACCOUNTS_PIPELINE_CONTINUITY_ACCEPTED: actual HTTP grant revocation/token rotation/last-admin guard while real MySQL→PostgreSQL worker keeps CDC and original identities");
    }
    void configure()throws Exception{Files.createDirectories(directory);platform.bind="127.0.0.1";platform.port=0;platform.authToken=TOKEN;platform.pollMillis=100;platform.tasksDirectory=directory.resolve("tasks").toString();platform.dataDirectory=directory.resolve("data").toString();platform.workerHeapMiB=256;
        pipeline.pipelineId=id;pipeline.source.clusterId=id;pipeline.source.host="mysql";pipeline.source.port=3306;pipeline.source.username="root";pipeline.source.password="Sync@Test123";pipeline.source.serverId=991735;pipeline.databases=Collections.singletonList(id);pipeline.chunkSize=1;pipeline.pollIntervalMillis=100;pipeline.retryDelayMillis=300;pipeline.leaseMillis=5000;pipeline.heartbeatMillis=300;pipeline.journal.path=Paths.get(platform.dataDirectory,"journals",id).toString();PipelineConfig.Target pg=new PipelineConfig.Target();pg.id="postgres";pg.product=TargetProduct.POSTGRESQL;pg.url="jdbc:postgresql://postgres:5432/sync_test?connectTimeout=3&socketTimeout=10";pg.username="sync_test";pg.password="Sync@Test123";pg.metadataSchema=id+"_meta";pg.mappings.put(id,id+"_copy");pipeline.targets.add(pg);pipeline.validate();}
    void run()throws Exception{configure();source("CREATE DATABASE "+Sql.mysql(id));String table=Sql.mysql(id)+".items";try{source("CREATE TABLE "+table+" (id INT PRIMARY KEY,value VARCHAR(100)) ENGINE=InnoDB");source("INSERT INTO "+table+" VALUES(1,'first')");startController();ObjectNode create=Model.JSON.createObjectNode();ObjectNode task=Model.JSON.valueToTree(pipeline);((ObjectNode)task.get("journal")).remove("path");create.set("config",task);require(request("/api/tasks","POST",create,"create_configuration_task").status==201,"Task creation failed");action("START");await(()->rows()==1);
        try(JdbcJournal journal=new JdbcJournal(pipeline.journalSettings())){String generation=(String)journal.status().get("generation");Journal.SnapshotState snapshot=journal.snapshot("source",TableSchema.identity(id,"","items"));require(snapshot!=null,"Snapshot metadata missing");String snapshotId=snapshot.snapshotId;long sequence=((Number)journal.status().get("lastSequence")).longValue();exerciseAccounts(journal,generation,snapshotId);stop();target("ALTER ROLE sync_test PASSWORD 'Rotated@Test123'");targetPassword="Rotated@Test123";source("INSERT INTO "+table+" VALUES(2,'after rotation')");action("CHECK");JsonNode operations=task().path("operations");require(operations.get(operations.size()-1).path("status").asText().equals("FAILED"),"Old target credential unexpectedly passed check");ObjectNode update=edited(targetPassword);Response preview=request(path()+"/configuration/validate","POST",update,null);require(preview.status==200&&!preview.body.path("migrationRequired").asBoolean(),"Credential rotation incorrectly needs migration");Response changed=commit(update,"rotate_postgres_password");require("STOPPED".equals(changed.body.path("desired").asText()),"Config update auto-started task");require(request(path()+"/configuration","PUT",update,"rotate_postgres_password").status==200,"Idempotent config replay failed");action("START");await(()->rows()==2);require(generation.equals(journal.status().get("generation")),"Rotation reset stream generation");require(snapshotId.equals(journal.snapshot("source",TableSchema.identity(id,"","items")).snapshotId),"Rotation created a new snapshot");require(((Number)journal.status().get("lastSequence")).longValue()>sequence,"CDC did not advance");
            stop();target("ALTER ROLE sync_test PASSWORD 'Sync@Test123'");targetPassword="Sync@Test123";source("INSERT INTO "+table+" VALUES(3,'after restore')");Response history=request(path()+"/configuration/history","GET",null,null);require(history.body.path("versions").size()==2,"Unexpected config history");require("legacy-admin".equals(history.body.path("versions").get(0).path("actorId").asText()),"Real authenticated editor missing");ObjectNode restore=Model.JSON.createObjectNode();restore.put("reference",history.body.path("versions").get(1).path("reference").asText());restore.put("expectedRevision",task().path("revision").asText());require(request(path()+"/configuration/restore/validate","POST",restore,null).status==200,"Restore preview failed");await(()->{Response result=request(path()+"/configuration/restore","POST",restore,"restore_original_credentials");if(result.status==409&&result.body.path("code").asText().equals("TASK_BUSY"))return false;require(result.status==200,"Restore rejected");return true;});action("START");await(()->rows()==3);require(snapshotId.equals(journal.snapshot("source",TableSchema.identity(id,"","items")).snapshotId),"Restore rewound/recreated snapshot");
            stop();String version=task().path("configurationVersion").asText();closeController();Files.deleteIfExists(Paths.get(platform.tasksDirectory,id+".yml"));Files.deleteIfExists(Paths.get(platform.dataDirectory,"worker-configs",id+".yml"));source("INSERT INTO "+table+" VALUES(4,'after controller restart')");startController();require(requestAs(OPERATOR,"/api/session","GET",null,null).status==401&&requestAs(ROTATED_OPERATOR,path(),"GET",null,null).status==404,"Restart revived revoked credentials/grants");require(version.equals(task().path("configurationVersion").asText()),"Restart lost committed config");require(Files.isRegularFile(Paths.get(platform.tasksDirectory,id+".yml")),"Missing projection was not recovered");action("START");await(()->rows()==4);require(generation.equals(journal.status().get("generation"))&&snapshotId.equals(journal.snapshot("source",TableSchema.identity(id,"","items")).snapshotId),"Controller restart reset checkpoint identity");stop();require(request(path()+"/configuration/history","GET",null,null).body.path("versions").size()==3,"Restore did not append version history");
        }Response audit=request("/api/audit/export?limit=1000","GET",null,null);require(audit.status==200,"Actual release audit export failed");String auditText=audit.body.toString();require(!auditText.contains(TOKEN)&&!auditText.contains(OPERATOR)&&!auditText.contains(ROTATED_OPERATOR)&&!auditText.contains("Sync@Test123")&&!auditText.contains("Rotated@Test123"),"Audit leaked credentials");require(auditText.contains("OPERATION_COMMITTED")&&auditText.contains("EDIT_CONFIG")&&auditText.contains("RESTORE_CONFIG")&&auditText.contains("FAILED"),"Actual asynchronous/configuration audit outcomes missing");int page=0;while(true){Path export=directory.resolve(String.format("audit-page-%03d.json",page++));Files.write(export,Model.JSON.writeValueAsBytes(audit.body));try{Files.setPosixFilePermissions(export,java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));}catch(UnsupportedOperationException ignored){}if(audit.body.path("next").isNull())break;require(page<100,"Audit fixture page bound exceeded");audit=request("/api/audit/export?limit=1000&after="+audit.body.path("next").asLong()+"&through="+audit.body.path("through").asLong(),"GET",null,null);require(audit.status==200,"Audit continuation failed");}System.out.println("AUDIT_PIPELINE_ACCEPTED: actual release configuration/HTTP/asynchronous outcomes, controller restart and credential-free native JSON exports");System.out.println("CONFIGURATION_PIPELINE_ACCEPTED: actual release Java8 HTTP/controller/workers, MySQL8.4 to PostgreSQL17, stopped target password rotation, failed old-credential check, opaque references/idempotent update, version restore and controller restart with missing projections; original stream/snapshot identities and CDC preserved");}finally{closeController();source("DROP DATABASE IF EXISTS "+Sql.mysql(id));}}
    public static void main(String[] args)throws Exception{new ConfigurationAcceptance().run();}
}
